class Solution {
public:
    int minSelection(vector<vector<int>>& availableIntervals,
                     vector<vector<int>>& targetIntervals) {
        // 1. sort and merge target intervals
        vector<pair<int,int>> target;
        target.reserve(targetIntervals.size());
        for (auto &v : targetIntervals) target.emplace_back(v[0], v[1]);
        sort(target.begin(), target.end(),
             [](const pair<int,int>& a, const pair<int,int>& b){
                 return a.first < b.first;
             });
        vector<pair<int,int>> merged;
        for (auto &p : target) {
            if (merged.empty() || p.first > merged.back().second) {
                merged.push_back(p);
            } else {
                merged.back().second = max(merged.back().second, p.second);
            }
        }

        // 2. sort available intervals by left endpoint
        vector<pair<int,int>> avail;
        avail.reserve(availableIntervals.size());
        for (auto &v : availableIntervals) avail.emplace_back(v[0], v[1]);
        sort(avail.begin(), avail.end(),
             [](const pair<int,int>& a, const pair<int,int>& b){
                 if (a.first != b.first) return a.first < b.first;
                 return a.second > b.second; // longer first for convenience
             });

        int n = (int)avail.size();
        int i = 0;               // pointer in avail
        long long cur = LLONG_MIN;
        int ans = 0;

        for (auto &seg : merged) {
            long long L = seg.first, R = seg.second;
            if (cur < L) cur = L;          // start of uncovered part
            while (cur < R) {
                long long far = cur;
                while (i < n && avail[i].first <= cur) {
                    far = max(far, (long long)avail[i].second);
                    ++i;
                }
                if (far == cur) return -1; // cannot extend
                ++ans;
                cur = far;
            }
        }
        return ans;
    }
};
